if cell_pos > cut:
    # The split must occur before the current character (at index pos-1).
    # Text before split: text[:pos-1]
    # Cell length before split: cell_pos - cell_size(char)

    # Calculate required padding
    padding_needed = cut - (cell_pos - cell_size(char))

    # Ensure padding is non-negative
    padding_needed = max(0, padding_needed)

    segment1_text = text[:pos-1] + " " * padding_needed
    segment2_text = text[pos:]

    return (
        _Segment(segment1_text, style, control),
        _Segment(segment2_text, style, control),
    )

